(() => {
  try {
    const stats = {};

    // 尝试获取游戏内部变量
    stats.gameSpeed = typeof currentSpeed !== 'undefined' ? currentSpeed : (typeof gameSpeed !== 'undefined' ? gameSpeed : null);
    stats.speedOptions = typeof speedOptions !== 'undefined' ? speedOptions : null;

    // 从页面提取更多实时数据
    const text = document.body.innerText;

    // 当前季节天数（从UI顶部）
    const seasonDayMatch = text.match(/(春季|夏季|秋季|冬季)\s*第\s*(\d+)\s*天/);
    if (seasonDayMatch) {
      stats.currentSeason = seasonDayMatch[1];
      stats.currentSeasonDay = parseInt(seasonDayMatch[2]);
    }

    // 从localStorage获取最新存档
    const saveStr = localStorage.getItem('farm_game_save_v1');
    if (saveStr) {
      const save = JSON.parse(saveStr);
      stats.saveDay = save.day;
      stats.saveSeason = save.season;
      stats.saveMoney = save.money;
      stats.saveStamina = save.stamina;
      stats.saveHealth = save.health;
      stats.saveFields = save.fields ? save.fields.length : 0;
      stats.saveNPC = save.npcFavor || save.npc || {};
      stats.saveSkills = save.skills || {};

      // 尝试获取好感度详细数据
      if (save.npcFavor) {
        stats.npcFavor = save.npcFavor;
      } else if (save.npc) {
        stats.npcFavor = save.npc;
      }

      // 田地详细状态
      if (save.fields) {
        stats.fieldDetails = save.fields.map((f, i) => ({
          index: i + 1,
          status: f.status,
          crop: f.crop,
          growth: f.growth,
          moisture: f.moisture,
          fertility: f.fertility,
          weeds: f.weeds,
          pests: f.pests
        }));
      }

      // 库存
      stats.inventory = save.inventory || {};

      // 当前任务
      stats.currentQuest = save.currentQuest || null;
      stats.questProgress = save.questProgress || {};

      // 其他数据
      stats.totalPlayedDays = save.totalPlayedDays || save.day;
      stats.rentedFields = save.rentedFields || 0;
      stats.houseLevel = save.houseLevel || 0;
      stats.pet = save.pet || null;
      stats.fishingSkill = save.fishingSkill || null;
    }

    // 从事件日志统计NPC好感度变化
    const eventLog = document.querySelector('.event-log, [class*="event"], [class*="log"]');
    if (eventLog) {
      stats.eventLogText = eventLog.innerText.substring(0, 500);
    }

    // 统计页面上的田地状态
    const fieldElements = document.querySelectorAll('[class*="field"], [class*="田地"]');
    stats.uiFieldCount = fieldElements.length;

    // 游戏速度按钮状态
    const speedBtns = document.querySelectorAll('button, [class*="speed"], [class*="倍"]');
    stats.speedBtnCount = speedBtns.length;

    return JSON.stringify(stats);
  } catch(e) {
    return JSON.stringify({error: e.message, stack: e.stack});
  }
})()
